insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('59da4899-d229-5b1a-a304-a9862deca661', 'Setor Centro, Região Episcopal Centro-Oeste.', '{"https://arquidiocesedecuritiba.org.br/paroquia/catedral-basilica-menor-nossa-senhora-da-luz-dos-pinhais"}', 'alta'),
  ('c6a112e5-dfe1-57cd-823a-846256efd4fd', 'Setor Centro, Região Episcopal Centro-Oeste. Igreja histórica do Largo da Ordem; o GCatholic a marca como paróquia e o site da Arquidiocese a lista entre as paróquias.', '{"https://arquidiocesedecuritiba.org.br/paroquia/igreja-da-ordem-terceira-de-sao-francisco-da-chagas"}', 'alta'),
  ('e2737899-3727-5d56-a56c-1ed0ee6e6399', 'Setor Centro, Região Episcopal Centro-Oeste. Igreja do Rosário (Largo da Ordem), também chamada Santuário das Almas no GCatholic, que a marca como paróquia; o site da Arquidiocese a lista entre as paróquias. Telefone: o site mostra "(41) 9 " antes do fixo; entrou o fixo.', '{"https://arquidiocesedecuritiba.org.br/paroquia/igreja-nossa-senhora-do-rosario"}', 'alta'),
  ('f748aa40-9923-5f6b-b799-558cfa51d717', 'Setor Almirante Tamandaré, Região Episcopal Norte. Sem horário: a página da paróquia no site da Arquidiocese não traz horários de missa. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/par-sao-pedro-apostolo"}', ''),
  ('266fcc01-db74-5e9c-a649-a202a886e542', 'Setor Almirante Tamandaré, Região Episcopal Norte. Fora do formato: Capela São José: sábado, 17h. Capela Divino Espírito Santo: sábado, 19h. Capela São Vicente de Paulo: sábado, 19h. Capela Nossa Senhora das Graças: sábado, sem hora na página. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-anjo-da-guarda"}', 'alta'),
  ('61fbc433-bb92-5df5-8b89-189f7398b658', 'Setor Santa Felicidade, Região Episcopal Centro-Oeste. Sem horário: a página da paróquia no site da Arquidiocese não traz horários de missa.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-bom-pastor"}', ''),
  ('28df2f63-1d8a-501f-be22-48cc85dbf584', 'Setor Orleans - Campo Comprido, Região Episcopal Centro-Oeste. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-cristo-ressuscitado"}', 'alta'),
  ('6786f663-9e00-5a56-b52d-88849892d375', 'Setor Centro, Região Episcopal Centro-Oeste. Telefone: o site mostra "(41) 9 " antes do fixo; entrou o fixo. Fora do formato: Novena em honra a Nossa Senhora do Monte Claro, mensal (celebração da Palavra), sem dia e hora na página. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-de-santo-estanislau"}', 'alta'),
  ('cefef000-5f4e-5929-8d67-dfc1659cfb25', 'Setor Centro, Região Episcopal Centro-Oeste. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-divino-espirito-santo"}', 'alta'),
  ('518304e0-7964-5e47-91dd-cb1cef178aef', 'Setor Colombo, Região Episcopal Norte. Telefone: o site mostra "(41) 9 " antes do fixo; entrou o fixo. Sem horário: a página da paróquia no site da Arquidiocese não traz horários de missa.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-imaculada-conceicao-atuba-colombo"}', ''),
  ('0a764eb8-a90e-5a81-9a7a-933488c04e5f', 'Setor Santa Felicidade, Região Episcopal Centro-Oeste. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-imaculada-conceicao-campo-magro"}', 'alta'),
  ('5ed800d2-a037-5524-8fdc-787f4e2973f7', 'Setor Rebouças, Região Episcopal Sul.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-imaculada-conceicao-guabirotuba"}', 'alta'),
  ('2677aec3-8ca5-5c81-97bc-c3a29731bc1c', 'Setor Rebouças, Região Episcopal Sul.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-imaculado-coracao-de-maria"}', 'alta'),
  ('f61dc277-61ba-5eac-bcf6-ab399f795cdb', 'Setor Pinhais, Região Episcopal Norte. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-maria-mae-da-igreja"}', 'alta'),
  ('7acf9eaa-84b6-58b8-a0bb-3c5e99d1a6ba', 'Setor Boqueirão, Região Episcopal Sul. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-menino-deus-guabirotuba"}', 'alta'),
  ('5dc27ffd-f3d9-598c-bb24-a86d82b022fe', 'Setor Portão, Região Episcopal Sul. Fora do formato: Quarta-feira, 19h: novena em louvor a Nossa Senhora Auxiliadora. Novena em louvor ao Menino Jesus de Praga, sem dia e hora na página.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-menino-jesus-de-praga"}', 'alta'),
  ('f6450118-d322-53b9-8529-92ca2ee6ebc8', 'Setor Campo Largo, Região Episcopal Centro-Oeste. Fora do formato: Capela São João Batista: quarta-feira, 19h, missa com novena. Capela Nossa Senhora Aparecida: sábado, 19h.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-menino-jesus"}', 'alta'),
  ('e5297885-d82e-521b-8a2c-46306fdb9e8e', 'Setor Santa Felicidade, Região Episcopal Centro-Oeste. Fora do formato: Novena de Nossa Senhora do Perpétuo Socorro: quarta-feira, 19h. Novena de Santa Rita: sexta-feira, 19h.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-n-sra-da-conceicao"}', 'alta'),
  ('a6987464-1235-55d0-9dbe-afce366334d9', 'Setor Campo Largo, Região Episcopal Centro-Oeste. Sem horário: a página da paróquia no site da Arquidiocese não traz horários de missa. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-aparecida-campo-largo"}', ''),
  ('0e16141f-d016-57a4-ab1e-4b39b19317da', 'Setor Santa Felicidade, Região Episcopal Centro-Oeste. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-aparecida-campo-magro"}', 'alta'),
  ('ac334ad5-a866-57b0-a612-c48db2fd0d12', 'Setor Pinhais, Região Episcopal Norte. Sem horário: a página da paróquia no site da Arquidiocese não traz horários de missa.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-aparecida-pinhais"}', ''),
  ('a4e2a407-23e6-57ca-8f2e-3e8beea88650', 'Setor Mercês, Região Episcopal Centro-Oeste. Fora do formato: Celebração da Palavra aos domingos, 10h. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-aparecida-seminario"}', 'alta'),
  ('81f0656e-59f7-58b6-8d22-38178659c3aa', 'Setor Pinheirinho, Região Episcopal Sul. Fora do formato: Novena de Nossa Senhora Aparecida: quarta-feira, 20h. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-aparecida-sitio-cercado"}', 'alta'),
  ('b1719841-a130-5d62-b486-529491003a04', 'Setor Cajuru, Região Episcopal Norte. O site da Arquidiocese registra a cidade como "Uberaba", que é bairro de Curitiba. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-aparecida-uberaba"}', 'alta'),
  ('5788792c-04af-5b56-a801-af4c09649eba', 'Setor Pinheirinho, Região Episcopal Sul. Fora do formato: Comunidade Vitória: quarta, 19h, e domingo, 9h30. Comunidade São Sebastião: sexta, 19h30, e domingo, 8h. Comunidade Santa Joana: sábado, 19h. Comunidade Nossa Senhora Aparecida da Luta: sábado, 19h. Comunidade Nossa Senhora de Fátima: domingo, 9h30.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-auxiliadora"}', 'alta'),
  ('e674278b-54e3-5c03-9efb-f83a33f6e156', 'Setor Campo Largo, Região Episcopal Centro-Oeste. Sem horário confirmado: a página da Arquidiocese tem dados repetidos de outra paróquia (ver nao_cabe). Fora do formato: A página desta paróquia traz horários de missa na matriz e nas capelas Nossa Senhora da Esperança e Nossa Senhora da Consolação iguais aos da página da Paróquia Nossa Senhora da Anunciação do Capão Raso; não entraram até a paróquia confirmar de qual das duas são.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-da-anunciacao-1"}', ''),
  ('a62b7820-a7ef-53cf-9172-b3853250f160', 'Setor Capão Raso, Região Episcopal Sul. Sem horário confirmado: a página da Arquidiocese tem dados repetidos de outra paróquia (ver nao_cabe). Fora do formato: A página desta paróquia traz horários de missa na matriz e nas capelas Nossa Senhora da Esperança e Nossa Senhora da Consolação iguais aos da página da Paróquia Nossa Senhora da Anunciação de Campo Largo; não entraram até a paróquia confirmar de qual das duas são. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-da-anunciacao-capao-raso"}', ''),
  ('0e9bf007-ddaa-50b8-bda7-02bc78153985', 'Setor Pinhais, Região Episcopal Norte. Fora do formato: Capela Bom Pastor: domingo, 10h. Capela Nossa Senhora do Carmo: domingo, 8h30. Capela Nossa Senhora Aparecida: domingo, 8h30.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-da-boa-esperanca"}', 'alta'),
  ('477b7b03-3465-5d22-a4a4-8dee0e2c17eb', 'Setor Capão Raso, Região Episcopal Sul.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-da-cabeca"}', 'alta'),
  ('db0181a3-2276-5b6c-beee-e409b29b4096', 'Setor Campo Largo, Região Episcopal Centro-Oeste. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedecuritiba.org.br/paroquia/paroquia-nossa-senhora-da-conceicao-2"}', 'alta'),
